def run_case(t: object, holder: object, provision: object, boundary: object, spec: dict, tmp: str, reached: set) -> dict:
    """Run one case against `holder.publication_status_command`: the launcher's seams on `t`, the nested helpers on their modules."""
    calls: list = []
    said: list = []
    root = Path(tmp)
    config = SimpleNamespace(project="demo", run_as_user=spec.get("owner", "syrd410-owner"))
    config_path = root / "demo.json"

    def norm(value):
        if isinstance(value, (list, tuple)):
            return [norm(v) for v in value]
        if isinstance(value, dict):
            return {str(k): norm(v) for k, v in value.items()}
        for obj, name in ((config, "CONFIG"), (runner, "RUNNER"), (_PIPE, "PIPE")):
            if value is obj:
                return name
        if isinstance(value, SimpleNamespace):
            return {"namespace": norm(vars(value))}
        if isinstance(value, Path):
            value = str(value)
        if isinstance(value, str):
            return value.replace(tmp, "<TMP>")
        return value

    def record(name, answer):
        def call(*args, **kwargs):
            reached.add(name)
            calls.append([name, norm(list(args)), norm(dict(sorted(kwargs.items())))])
            return answer(*args, **kwargs)
        return call

    def runner(argv, **kwargs):
        calls.append(["runner", norm(list(argv)), norm(dict(sorted(kwargs.items())))])
        path = str(argv[-1])
        which = "pub" if "publish-key" in path else "shared"
        if not spec.get(which, True):
            return SimpleNamespace(returncode=1, stdout="", stderr="no such file")
        return SimpleNamespace(returncode=0, stdout=f"256 SHA256:{which}{which}{which} key (ED25519)\n", stderr="")

    def evidence(project, **kwargs):
        detail = " (recorded yesterday)" if spec.get("detail") else ""
        return SimpleNamespace(stale=[f"the {n} key changed" for n in ("publication", "shared")][: spec.get("stale", 0)],
                               publication=SimpleNamespace(state="accepted", detail=detail.strip()),
                               shared=SimpleNamespace(state="refused" if spec.get("ready", True) else "unverified", detail=detail.strip()))

    def finding(project, **kwargs):
        return SimpleNamespace(state="write-refused" if spec.get("verify") == "refused" else "write-allowed",
                               detail="the forge said no" if spec.get("detail") else "")

    real_fingerprint = t._public_key_fingerprint
    on_launcher = {"current_user_name": record("current_user_name", lambda: "syrd410-me"),
                   "home_dir_for_user": record("home_dir_for_user", lambda user: root / "home" / user),
                   "_plan_data_from_config": record("_plan_data_from_config", lambda cfg, path: {"owner_github_key_name": "k410", "owner_github_host_alias": "gh410"}),
                   "switchyard_privileged_provision_root": record("switchyard_privileged_provision_root", lambda: root / "provision"),
                   "_public_key_fingerprint": record("_public_key_fingerprint", real_fingerprint)}
    on_provision = {"resolve_owner_github_identity": record("resolve_owner_github_identity", lambda home, **k: SimpleNamespace(resolved=spec.get("resolved", True), key_name="k410")),
                    "owner_github_key_path": record("owner_github_key_path", lambda home, *, key_name: f"{home}/.ssh/{key_name or 'default-key'}"),
                    "publish_identity_path": record("publish_identity_path", lambda project: f"/nonexistent/syrd410/publish/{project}/publish-key")}
    on_boundary = {"resolve_pinned_remote": record("resolve_pinned_remote", lambda project, **k: ("git@forge.invalid:syrd/demo.git", "") if spec.get("remote", True) else ("", "no remote record under <provision>")),
                   "verify_shared_credential": record("verify_shared_credential", finding),
                   "read_cutover_evidence": record("read_cutover_evidence", evidence),
                   "cutover_state": record("cutover_state", lambda ev: boundary.CUTOVER_READY if spec.get("ready", True) else "configured-unverified"),
                   "shared_credential_check_command": record("shared_credential_check_command", lambda remote, **k: ["syrd410-check", "--as", k["owner_user"], "a key's path", k["identity_file"], remote])}
    saved = [(target, {n: getattr(target, n) for n in names}) for target, names in ((t, on_launcher), (provision, on_provision), (boundary, on_boundary))]
    for target, names in ((t, on_launcher), (provision, on_provision), (boundary, on_boundary)):
        for n, f in names.items():
            setattr(target, n, f)
    verify = {} if spec.get("verify") == "default" else {"verify": spec.get("verify", "off") != "off"}
    try:
        got = holder.publication_status_command(config, config_path=config_path, **verify, runner=runner,
                                                print_func=lambda line: said.append(norm(line)) or calls.append(["say"]))
        answer = norm(got)
    except AssertionError:
        raise
    except BaseException as exc:  # noqa: BLE001 -- the baseline's own answer, whatever it raises
        answer = {"raised": type(exc).__name__, "message": norm(str(exc))}
    finally:
        for target, names in saved:
            for n, f in names.items():
                setattr(target, n, f)
    return {"answer": answer, "said": said, "calls": calls}


def fingerprint_case(holder: object, spec: dict) -> dict:
    calls: list = []

    def runner(argv, **kwargs):
        calls.append([list(argv), sorted(kwargs.items(), key=lambda kv: kv[0]) and {k: ("PIPE" if v is _PIPE else v) for k, v in sorted(kwargs.items())}])
        shown = SimpleNamespace(stdout=spec["stdout"], stderr="")
        if "rc" in spec:
            shown.returncode = spec["rc"]
        return shown
    return {"answer": holder._public_key_fingerprint("/nonexistent/syrd410/key.pub", runner=runner), "calls": calls}


def parser_cases(holder: object) -> dict:
    saved = os.environ.get("COLUMNS")
    os.environ["COLUMNS"] = "100"
    try:
        parser = holder._build_switchyard_publication_status_parser()
        out = {"help": parser.format_help(), "prog": parser.prog}
        for label, argv in PARSES.items():
            try:
                out[label] = vars(parser.parse_args(argv))
            except SystemExit as exc:  # a parse the baseline accepts must not start exiting: record it as an answer
                out[label] = {"exit": exc.code}
        return out
    finally:
        if saved is None:
            os.environ.pop("COLUMNS", None)
        else:
            os.environ["COLUMNS"] = saved


_PIPE = subprocess.PIPE
# ----------------------------------------------------------------------------------------------------------------------


def check(condition: bool, detail: str) -> None:
    global CHECKS
    assert condition, detail
    CHECKS += 1


def python(probe: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run([sys.executable, "-c", probe], cwd=ROOT, capture_output=True, text=True,
                          env={"PATH": "/usr/bin:/bin"}, check=False)


class patched:
    def __init__(self, target: object, **values: object) -> None:
        self.target, self.values = target, values

    def __enter__(self) -> None:
        self.saved = {name: getattr(self.target, name) for name in self.values}
        for name, value in self.values.items():
            setattr(self.target, name, value)

    def __exit__(self, *exc: object) -> None:
        for name, value in self.saved.items():
            setattr(self.target, name, value)


def refuse(what: str):
    def refused(*args: object, **kwargs: object) -> object:
        raise AssertionError(f"{what} was called: {args} {kwargs}")
    return refused


class contained:
    """Spawns, signals, account lookups, connections and the seams' own definitions refused."""

    def __enter__(self) -> None:
        self.parts = [patched(subprocess, run=refuse("subprocess.run"), Popen=refuse("subprocess.Popen")),
                      patched(os, kill=refuse("os.kill")), patched(pwd, getpwnam=refuse("pwd.getpwnam"), getpwuid=refuse("pwd.getpwuid")),
                      patched(socket.socket, connect=refuse("socket.connect"), connect_ex=refuse("socket.connect_ex")),
                      patched(publication_boundary, verify_shared_credential=refuse("publication_boundary.verify_shared_credential")),
                      *(patched(home, **{name: refuse(f"{home.__name__}.{name}") for name in names}) for home, names in HOMES.items())]
        for part in self.parts:
            part.__enter__()

    def __exit__(self, *exc: object) -> None:
        for part in reversed(self.parts):
            part.__exit__(*exc)


def run(spec: dict) -> dict:
    with tempfile.TemporaryDirectory(prefix="syrd410-test.") as tmp, contained():
        return run_case(t, m, project_provision, publication_boundary, spec, os.path.realpath(tmp), REACHED)


def test_the_guard_itself_refuses_a_spawn_a_lookup_and_each_step_past_the_launcher() -> None:
    attempts = [lambda: subprocess.run(["true"]), lambda: subprocess.Popen(["true"]), lambda: os.kill(os.getpid(), 0),
                lambda: pwd.getpwuid(0), lambda: socket.socket().connect(("127.0.0.1", 9)),
                lambda: publication_boundary.verify_shared_credential("demo"),
                *(lambda home=home, name=name: getattr(home, name)("syrd410-owner") for home, names in HOMES.items() for name in names)]
    for attempt in attempts:
        with contained():
            try:
                attempt()
            except AssertionError as exc:
                refused = " was called: " in str(exc)
            else:
                refused = False
        check(refused, "the guard refuses a spawn, a signal, an account lookup, a connection, the forge check and each seam's own definition")


