def test_every_status_is_the_baselines() -> None:
    check(sorted(CASES) == sorted(k[len("command:"):] for k in GOLDEN if k.startswith("command:")), "every measured case is asserted, and nothing else")
    for label, spec in CASES.items():
        got = run(spec)
        check(got == GOLDEN[f"command:{label}"], f"{label}: the baseline's answer, every line and every call in order: {got}")


def test_the_forge_is_asked_only_under_verify() -> None:
    for label, spec in CASES.items():
        asked = [c for c in GOLDEN[f"command:{label}"]["calls"] if c[0] == "verify_shared_credential"]
        wants = spec.get("verify", "off") not in ("off", "default") and spec.get("remote", True)
        check(len(asked) == (1 if wants else 0), f"{label}: the one write boundary is reached only under --verify: {asked}")


def test_the_fingerprint_reader_and_the_parser_are_the_baselines() -> None:
    with contained():
        for label, spec in FINGERPRINTS.items():
            got = fingerprint_case(m, spec)
            check(got == GOLDEN[f"fingerprint:{label}"], f"fingerprint {label}: {got}")
    check(parser_cases(m) == GOLDEN["parser"], "the parser's help, program name and every parse")


def test_every_launcher_seam_is_reached() -> None:
    expected = {name for reads in SEAMS.values() for name in reads}
    check(expected <= REACHED, f"a stand-in on the launcher reached every seam: missing {sorted(expected - REACHED)}")


STRUCTURE = ("test_the_module_loads_nothing_of_switchyards_at_import", "test_either_import_order_gives_one_set_of_objects_and_the_defaults",
             "test_the_seams_read_through_the_launcher_and_the_helpers_imported_inside", "test_the_launcher_reexports_the_three_and_dispatches_through_them")
LAST = ("test_every_launcher_seam_is_reached",)


def main() -> int:
    names = sorted(name for name, value in globals().items() if name.startswith("test_") and callable(value))
    for name in [*STRUCTURE, *(name for name in names if name not in STRUCTURE + LAST), *LAST]:
        globals()[name]()
    print(f"publication_status_boundary_test: {CHECKS} checks ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
